/bin/bash -lc "python -c 'import os; from bioblend.galaxy import GalaxyInstance; hid=\"bbd44e69cb8906b5c877444e443a0664\"; key=open(os.environ[\"GALAXY_API_KEY_FILE\"]).read().strip(); gi=GalaxyInstance(url=\"https://usegalaxy.org\",key=key); updates=[(\"f9cad7b01a472135536125bdc546289f\",\"KL_counts\"),(\"f9cad7b01a472135a2c8e5ad06f44b70\",\"WL_counts\")]; out=[]; 
for did,name in updates:
    try:
        res=gi.histories.update_dataset(hid,did,name=name); out.append({\"id\":did,\"name\":name,\"ok\":True})
    except Exception as e:
        try:
            res=gi.datasets.update_dataset(did,name=name); out.append({\"id\":did,\"name\":name,\"ok\":True})
        except Exception as e2: out.append({\"id\":did,\"name\":name,\"ok\":False,\"error\":str(e2)})
print(out)'"

