for did,name in updates:
    try: gi.histories.update_dataset(hid,did,name=name); out.append({\"id\":did,\"name\":name,\"ok\":True})
    except Exception:
        try: gi.datasets.update_dataset(did,name=name); out.append({\"id\":did,\"name\":name,\"ok\":True})
        except Exception as e2: out.append({\"id\":did,\"name\":name,\"ok\":False,\"error\":str(e2)})
print(out)'"

